using System;
using System.Collections.Generic;

namespace Elemento.Domain
{
    [Serializable]
    public sealed class CardDefinitionData
    {
        public int DefinitionId;
        public string Name;
        public int ConfigCount;
        public int ChoiceCount;
        public int ChanceCount;
        public int FilterFlags;
        public int[] Points;
        public int[] Multipliers;
        public int[] Bombs;
        public int[] Shields;
        public int WildPoints;
        public int WildMultiplier;
        public int WildBomb;
        public int WildShield;
        public int WildZoneHeal;
        public int WildFreeze;
        public int WildLightning;
        public bool IsPowerCard;

        public CardDefinitionData(int inDefinitionId, string inName, int inConfigCount,
            int inChoiceCount, int inChanceCount, int inFilterFlags, int[] inPoints,
            int[] inMultipliers, int[] inBombs, int[] inShields, int[] inWild, bool inIsPowerCard)
        {
            this.DefinitionId = inDefinitionId;
            this.Name = inName;
            this.ConfigCount = inConfigCount;
            this.ChoiceCount = inChoiceCount;
            this.ChanceCount = inChanceCount;
            this.FilterFlags = inFilterFlags;
            this.Points = inPoints;
            this.Multipliers = inMultipliers;
            this.Bombs = inBombs;
            this.Shields = inShields;
            this.WildPoints = inWild[0];
            this.WildMultiplier = inWild[1];
            this.WildBomb = inWild[2];
            this.WildShield = inWild[3];
            this.WildZoneHeal = inWild[4];
            this.WildFreeze = inWild[5];
            this.WildLightning = inWild[6];
            this.IsPowerCard = inIsPowerCard;
        }

        public CardInstanceData CreateCard(string inId = null)
        {
            return new CardInstanceData
            {
                Id = inId,
                DefinitionId = this.DefinitionId,
                DefinitionName = this.Name,
                IsPowerCard = this.IsPowerCard,
                Points = (int[])this.Points.Clone(),
                Multipliers = (int[])this.Multipliers.Clone(),
                Bombs = (int[])this.Bombs.Clone(),
                Shields = (int[])this.Shields.Clone(),
                WildPoints = this.WildPoints,
                WildMultiplier = this.WildMultiplier,
                WildBomb = this.WildBomb,
                WildShield = this.WildShield,
                WildZoneHeal = this.WildZoneHeal,
                WildFreeze = this.WildFreeze,
                WildLightning = this.WildLightning
            };
        }
    }

