        public static readonly IReadOnlyList<CardDefinitionData> PowerCards =
            Array.AsReadOnly(new CardDefinitionData[]
        {
            new CardDefinitionData(0, "Card - Power - Heal Zone", 10, 0, 0, 8192, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0, 10, 0, 0 }, true),
            new CardDefinitionData(1, "Card - Power - Freeze Zone", 12, 0, 0, 16384, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0, 0, 5, 0 }, true),
            new CardDefinitionData(2, "Card - Power - Lightning", 15, 0, 0, 32768, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0 }, new[] { 0, 0, 0, 0, 0, 0, 5 }, true),
        });

        public static CardInstanceData CreatePowerCard(EPowerCardType inType)
        {
            switch (inType)
            {
                case EPowerCardType.Heal: return PowerCards[0].CreateCard();
                case EPowerCardType.Freeze: return PowerCards[1].CreateCard();
                case EPowerCardType.Lightning: return PowerCards[2].CreateCard();
                default: throw new ArgumentOutOfRangeException(nameof(inType));
            }
        }

        public static List<CardInstanceData> CreateChoiceDeck()
        {
            List<CardInstanceData> cards = new();
            foreach (var definition in NormalCards)
            {
                for (int i = 0; i < definition.ChoiceCount; i++)
                    cards.Add(definition.CreateCard());
            }
            return cards;
        }

        public static List<CardInstanceData> CreatePowerDeck()
        {
            List<CardInstanceData> cards = new();
            foreach (var definition in PowerCards)
            {
                for (int i = 0; i < definition.ConfigCount; i++)
                {
                    var card = definition.CreateCard();
                    // CardsManager indexes each expanded copy, not each config.
                    card.DefinitionId = cards.Count;
                    cards.Add(card);
                }
            }
            return cards;
        }
    }
